// Flat lookup by id
const SPELLS_BY_ID = SPELLS_2024.reduce(function(m, s) { m[s.id] = s; return m; }, {});

// Grouped by level for the picker
const SPELLS_BY_LEVEL = SPELLS_2024.reduce(function(m, s) {
  if (!m[s.level]) m[s.level] = [];
  m[s.level].push(s);
  return m;
}, {});
